import java.util.Scanner;

public class OneBasedArithmetic {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        long[] ones = new long[17];
        for (int i = 1; i < 17; i++) {
            ones[i] = 10 * ones[i - 1] + 1;
        }
        long result = compute(ones, n, 16);
        System.out.println(result);
        scanner.close();
    }

    private static long compute(long[] ones, long n, int idx) {
        long quotient = n / ones[idx];
        n %= ones[idx];
        long totalUsed = quotient * idx;
        if (n == 0) {
            return totalUsed;
        } else {
            return totalUsed + Math.min(compute(ones, n, idx - 1),
                    idx + compute(ones, ones[idx] - n, idx - 1));
        }
    }
}
